from save_review import save
save(1349,{2:'通讯器在英文中也称 Vox-set、Comm-link 或 Communicator，是帝国卫队用来远距离传达命令的精密可靠设备，可传输声音或视听信号，并通过窄束发射器与信号解码器接入战略和战术指挥网络。',4:'Cadian Guardsman with a vox-caster 配备通讯器的卡迪亚卫队士兵',7:'通讯器的外形、尺寸因产地而异，既有独立手持式、头盔式、腕带式，也有射程更远的背负式；车载型号还可升级为增强通讯设备。它通过不断变化的频率降低被侦测的风险，并以严密屏蔽抵御电磁干扰。即使信号被截获，没有专门的复杂解密设备，也很难读出内容。因此，它可建立封闭频道，只有预先持有获准解码密钥的另一台设备才能接收。',9:'vox-caster 通讯器',11:'通讯距离随型号大小而异。手持式可达100公里，背负式更远，能跨越整颗行星，或与轨道上的星舰联络；车载型号的通讯距离可达1,000万英里。',13:'将通讯器设为广播白噪声后，便能把它用作临时短程干扰器，扰乱敌方通讯频道。它也有日志功能，可保存收到的通讯内容。用线缆直接连接缴获的敌方设备，就能复制其中的日志，再由内置翻译系统解读。',15:'通讯器可让指挥单位将指挥效能传递给其他部队，升级为大功率通讯器后尤其有效。它允许指挥官同时向小队发出多条消息，普通型号则一次只能发送一条。不过，军旗等装备的作用无法通过通讯传递，因为士兵必须亲眼看见军旗，才能从中获得信念。',19:'浮夸级音阵阵列由失落已久的铸造世界乌尔瓦克斯制造，是一种全频大功率通讯阵列，能够将命令迅速传遍作战分遣队。',22:'号角音阵阵列是风暴军为风暴忠嗣军特种作战部队部署的主要移动通讯系统。它是军用音讯设备中的杰作，能够占据指定频段，将各分遣队风暴忠嗣队长清晰、分明的命令送达部下。',27:'大使音阵是阿斯塔特军团使用的信标与通讯阵列，可持续联络邻近地区或高空轨道上的友军，使增援部队精确部署在附近，并引导打击准确命中目标。',30:'索尼格拉夫160是混沌部队使用的一种古老、不可便携的通讯器。它可接入主指挥频道和数据中继，成为主要通讯网络的一部分。解密模块须以实体钥匙启动，日志则至少能保存八个月的通讯记录。',33:'Mk.IIC 是一种便携式通讯器。',35:'Munitorum Mk IIc Vox Caster (Factorum Finish) 军务部 Mk.IIc 通讯器（工厂涂装）',38:'西塔-901是一种便携式通讯器。',40:'Vox-Caster Theta-901 西塔-901通讯器',48:'Vox 在拉丁语中意为“声音”。'},notes={2:'Vox-caster依据GW-04/GW-11同版索引第31页采用通讯器；原音阵发射器、音阵释放器保留对照。其他专名中的vox不机械替换。',13:'英文captioned依上下文应为captured，即缴获的设备；不是给设备添加字幕。',15:'standards为军旗，不是标准；Master Vox依据官方索引第15页译大功率通讯器。',35:'Finish指表面处理或涂装，不认定为抛光。'},terms=[('Vox-caster','通讯器'),('Master Vox','大功率通讯器'),('Bombast-Class Vox-Array','浮夸级音阵阵列'),('Urvax','乌尔瓦克斯'),('Clarion Vox Array','号角音阵阵列'),('Nuncio-Vox','大使音阵'),('Sonegraph 160','索尼格拉夫160'),('Theta-901','西塔-901')],title='通讯器 Vox-caster')
save(1350,{2:'全频干扰器是星际战士先锋渗透者使用的电子战设备，能截获广泛频段上的信号，扰乱频率、瘫痪敌方通讯。'},terms=[('Omni-Scrambler','全频干扰器')])
save(1351,{2:'时间扭曲器是导师战团正在实战测试的先进帝国设备，外形是一只人类手掌可以托住的小型机械盒。启动后，它将极微小的一部分亚空间吸入内部，把其中的能量转化为亚原子粒子，在盒子周围很小的球形区域内改变时间流动。区域内的人会感觉外界变慢，而自己能够更快行动。其范围可覆盖十名星际战士，但使用时会产生极强的失向感，即使训练多年，也难以让心智完全适应。它还有一个缺点：对机械和载具不起作用。'},terms=[('Timewarper','时间扭曲器')])
save(1352,{2:'冷冻箱是星际战士战团使用的便携式储存设备，至少能够容纳一个中队成员的基因种子。配属攻击摩托中队的药剂师可将它装在摩托上，用来回收战斗兄弟的基因种子。'},terms=[('Cryo-Box','冷冻箱')])
save(1353,{2:'医疗套件是星际战士药剂师的战地医疗工具组，包含救治伤员、使其尽快恢复作战能力所需的器具。',11:'Sterile clay for sealing wounds. 用于封闭伤口的无菌黏土',13:'刽子手装置——为伤重不治的星际战士实施安乐死。',15:'碳合金基因提取器——用于从阵亡战士体内取出基因存收腺，回收基因种子。',17:'其他部件可包括链锯刃，以及穿透盔甲的医疗钻。深孔型将链锯刃所在位置下移，并改用圆盘锯；其重点是钻穿装甲，尽快回收基因种子。哈根型的钻头更大、更强，不仅能处理常规星际战士盔甲，也能穿透终结者盔甲。',22:'平静针——圣血天使圣血祭司使用的特殊腕装式基因提取手枪，用于为重伤战士实施安乐死。',24:'放血器——圣血天使圣血祭司携带的特殊基因提取器，也可充当武器。',26:'莫凯之牙——太空野狼的狼牧师携带的特殊基因提取器。'},notes={13:'Carnifex在此是医疗器械，不能套用同名泰伦生物的身份。',17:'原文对链锯刃下移与替换的叙述略显含混，保留两项动作，不据图像之外的信息重设计结构。'},terms=[('Narthecium','医疗套件'),('Hagen Pattern Narthecium','哈根型医疗套件'),('Acus Placidus','平静针'),('Exsanguinator','放血器'),('Fang of Morkai','莫凯之牙')])
save(1354,{2:'螺旋型医疗套件是阿斯塔特修会医疗人员常用装备的增强版本，本身也是帝国遗物。',5:'这套多功能手术工具配有多光谱分析仪、生物工程神经刺激剂混合物和血肉催化剂，还装有皮层探测器及弗尔克赖特锯齿纳米锯，能锯开最坚固的动力盔甲。使用它的人甚至能将伤势致命的战斗兄弟从死亡边缘救回。不屈远征激战期间，螺旋型医疗套件也是持炬舰队可使用的帝国遗物之一。'},notes={5:'fulcrite为锯齿材料专名，暂音译弗尔克赖特；原译附齿遗漏了材料名。rages为战事激烈进行，不是远征开始。'},terms=[('Helix-pattern Narthecium','螺旋型医疗套件'),('Fulcrite','弗尔克赖特')])
save(1355,{2:'医疗臂铠是星际战士先锋螺旋医疗员佩戴的专用医疗装置，相当于药剂师医疗套件的缩小版。它既能从阵亡战斗兄弟体内取出并储存基因种子，也能提供刺激剂，使伤员恢复作战能力。'},notes={2:'Helix Adept沿已定螺旋医疗员，区别正式药剂师；stim-charges不是兴奋弹。'},terms=[('Helix Gauntlet','医疗臂铠')])
save(1356,{2:'刽子手是星际战士药剂师的装备，用来为伤重无法救治的战士施予“帝皇安宁”，即安乐死。它形似手枪，将管口抵在伤员太阳穴后启动，便会推动金属活塞穿过颅骨进入脑部，使其迅速、几乎无痛地死亡。'},terms=[('Carnifex (medical tool)','刽子手'),("The Emperor’s Peace",'帝皇安宁')])
save(1357,{2:'手榴弹是一类用于杀伤或扰乱敌方部队、破坏单个载具的手持装置。它们可设计为用手投掷或安放，也可通过榴弹发射器、投索等装置投射。',7:'不同手榴弹有不同效果。《战锤40,000》第一、二版提供了许多类型，多数种族和军队都能使用，并常有手榴弹与导弹两种形式。从第三版起，各军队在规则上只使用少数类型；底稿所述时期，涡流手榴弹重新出现在启示录规模的战斗中。欧克制造的手榴弹则称为棍子炸弹。',12:'破片手榴弹——手投版本可在冲锋前震慑敌方步兵；榴弹发射器所用的弹药则在爆炸时将破片散布于一定区域。',18:'EMP手榴弹——钛族专用，用来对付轻型载具。',21:'穿甲手榴弹——将爆炸威力高度集中于特定方向，以破开厚重装甲，作用方式与破片手榴弹相反。',40:'Neurostun Grenade 神经震晕手榴弹',41:'Psyk-out 反灵手榴弹'},notes={7:'保留原文所述规则版本演变；原文recently不代表当前出版状态。',41:'Psyk-out沿既定反灵武器词根，避免按普通英语写成心灵崩溃。'},terms=[('Grenade','手榴弹'),('Frag Grenade','破片手榴弹'),('Krak Grenade','穿甲手榴弹'),('Stikkbomb','棍子炸弹'),('Neurostun Grenade','神经震晕手榴弹'),('Psyk-out Grenade','反灵手榴弹')])
save(1358,{2:'破片手榴弹又称碎裂手榴弹，是小型杀伤人员武器。爆炸时会抛出数千块细小、致命的金属碎片，在己方发起冲锋时削弱敌人依托掩体的优势。',7:'其结构和作用方式都很简单：爆炸核心装有以保险销固定的引信，外面包覆钢壳。起爆后，弹壳裂成不规则碎片，高速飞散。外壳通常刻有凹槽，既便于握持，也使其在爆炸时形成更多破片。',9:'Frag grenades carried by a Stormtrooper 风暴兵携带的破片手榴弹',11:'一枚破片手榴弹重约1公斤，爆炸半径为3至5米。'},terms=[('Frag Grenade','破片手榴弹')])
save(1359,{2:'穿甲手榴弹是反坦克武器，以集中内爆的方式破开载具等装甲目标；破片手榴弹则主要杀伤人员。它的爆炸半径只有破片手榴弹的一半，因此在目标上的安放位置也需要更加精确。'},terms=[('Krak Grenade','穿甲手榴弹')])
save(1360,{5:'据说它爆发时如微型太阳般耀眼，受到强光照射者会本能地捂住双眼。星际战士能避免被这种光致盲，因此尤其适合在近战中使用。'},terms=[('Photon Flash Flare','光子闪光弹')])
save(1361,{2:'震撼手榴弹是星际战士掠夺者小队使用的闪光震撼弹，起爆时发出刺耳轰鸣，使他们能趁机接近敌人，展开近战。'},terms=[('Shock Grenade','震撼手榴弹')])
save(1362,{2:'窒息手榴弹释放非致命气体，使吸入者剧烈呛咳、呼吸困难，往往倒地失去行动能力，成为容易攻击的目标。只有佩戴呼吸器，或穿着与外界空气完全隔绝的装甲，才能免受影响。'},notes={2:'respirators与密封装甲是两种防护方式，不能将完全隔绝大气同时硬套到两者上。'},terms=[('Choke Grenade','窒息手榴弹')])
